import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { readFile } from 'node:fs/promises';
import { PGlite } from '@electric-sql/pglite';
import { PGLiteSocketServer } from '@electric-sql/pglite-socket';
import { renderToStaticMarkup } from 'react-dom/server';
import { SWRConfig } from 'swr';
import { canManageTeamMembers } from '@/lib/auth/team-permissions';

const request = vi.hoisted(() => ({ token: '' }));
vi.mock('next/headers', () => ({
  cookies: async () => ({
    get: (name: string) =>
      name === 'session' && request.token ? { value: request.token } : undefined
  })
}));

let sql: PGlite;
let socket: PGLiteSocketServer;
let actions: typeof import('@/app/(login)/actions');
let queries: typeof import('@/lib/db/queries');
let session: typeof import('@/lib/auth/session');
let client: typeof import('@/lib/db/drizzle')['client'];
let Page: typeof import('@/app/(dashboard)/dashboard/page')['default'];
let GET: typeof import('@/app/api/team/route')['GET'];

beforeAll(async () => {
  sql = await PGlite.create();
  await sql.exec(await readFile('lib/db/migrations/0000_soft_the_anarchist.sql', 'utf8'));
  socket = new PGLiteSocketServer({
    db: sql, port: 0, host: '127.0.0.1', maxConnections: 10
  });
  await socket.start();
  process.env.POSTGRES_URL = `postgresql://postgres:postgres@${socket.getServerConn()}/postgres`;
  process.env.AUTH_SECRET = 'local-team-permissions-regression-secret';
  process.env.STRIPE_SECRET_KEY = 'sk_test_local_no_payment_requests';
  actions = await import('@/app/(login)/actions');
  queries = await import('@/lib/db/queries');
  session = await import('@/lib/auth/session');
  ({ client } = await import('@/lib/db/drizzle'));
  ({ default: Page } = await import('@/app/(dashboard)/dashboard/page'));
  ({ GET } = await import('@/app/api/team/route'));
});

afterAll(async () => {
  await client?.end({ timeout: 3 });
  await socket?.stop();
  await sql?.close();
});

async function login(id: number) {
  request.token = await session.signToken({
    user: { id }, expires: new Date(Date.now() + 60000).toISOString()
  });
}

beforeEach(async () => {
  // Insert memberships out of ID order to exercise consistent current-team selection.
  await sql.exec(`
    TRUNCATE activity_logs, invitations, team_members, teams, users RESTART IDENTITY CASCADE;
    INSERT INTO users(id,name,email,password_hash,role) VALUES
      (1,'Owner','owner@fixture.invalid','unused','member'),
      (2,'Member','member@fixture.invalid','unused','owner'),
      (3,'Target','target@fixture.invalid','unused','member'),
      (4,'Other owner','other@fixture.invalid','unused','owner'),
      (5,'No team','no-team@fixture.invalid','unused','owner');
    INSERT INTO teams(id,name) VALUES (1,'Current team'), (2,'Other team');
    INSERT INTO team_members(id,user_id,team_id,role) VALUES
      (5,2,2,'owner'), (3,3,1,'member'), (1,1,1,'owner'), (2,2,1,'member'), (4,4,2,'owner');
  `);
  await login(1);
});

async function snapshot() {
  return {
    members: (await sql.query<{ id: number }>('SELECT * FROM team_members ORDER BY id')).rows,
    invitations: (await sql.query('SELECT * FROM invitations ORDER BY id')).rows,
    activity: (await sql.query('SELECT * FROM activity_logs ORDER BY id')).rows
  };
}

function remove(value: string | null) {
  const form = new FormData();
  if (value !== null) form.set('memberId', value);
  return actions.removeTeamMember({}, form);
}

function invite(role = 'member') {
  const form = new FormData();
  form.set('email', 'new@fixture.invalid');
  form.set('role', role);
  // A caller-supplied team must never determine the mutation's team.
  form.set('teamId', '2');
  form.set('teamRole', 'owner');
  return actions.inviteTeamMember({}, form);
}

async function markup() {
  const team = await queries.getTeamForUser();
  const user = await queries.getUser();
  return renderToStaticMarkup(
    <SWRConfig value={{
      provider: () => new Map(),
      fallback: { '/api/team': team, '/api/user': user },
      revalidateOnMount: false
    }}>
      <Page />
    </SWRConfig>
  );
}

describe('team permissions regression cases', () => {
  it.each(['member', 'admin', '', null, undefined])(
    'fails closed for membership role %s',
    (role) => {
      expect(canManageTeamMembers(role)).toBe(false);
    }
  );

  it('allows the owner membership role', () => {
    expect(canManageTeamMembers('owner')).toBe(true);
  });

  it('uses the same current membership in API, queries and direct actions', async () => {
    await login(2);
    expect(await queries.getUserWithTeam(2)).toMatchObject({
      teamId: 1, teamRole: 'member', user: { role: 'owner' }
    });
    const response = await GET();
    expect(response.status).toBe(200);
    expect(await response.json()).toMatchObject({ id: 1, currentUserRole: 'member' });
    const before = await snapshot();
    expect(await invite('owner')).toHaveProperty('error');
    expect(await remove('4')).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it.each([
    null, '', ' ', '0', '-3', '3.5', '3.0', '3e0', '0x3', '+3',
    '3junk', ' 3', '3 ', '2147483648', '9007199254740993'
  ])('rejects invalid browser memberId %s without any writes', async (value) => {
    const before = await snapshot();
    expect(await remove(value)).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('rejects a file-valued memberId', async () => {
    const form = new FormData();
    form.set('memberId', new Blob(['3']), 'member.txt');
    const before = await snapshot();
    expect(await actions.removeTeamMember({}, form)).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it.each(['4', '999'])('does not log success for foreign or missing member %s', async (id) => {
    const before = await snapshot();
    expect(await remove(id)).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('removes only the selected membership and logs once, including on repeated requests', async () => {
    const membersBefore = (await snapshot()).members;
    expect(await remove('3')).toHaveProperty('success');
    const after = await snapshot();
    expect(after.members).toEqual(membersBefore.filter((member) => member.id !== 3));
    expect(after.activity).toEqual([
      expect.objectContaining({ team_id: 1, user_id: 1, action: 'REMOVE_TEAM_MEMBER' })
    ]);
    expect(await remove('3')).toHaveProperty('error');
    expect(await snapshot()).toEqual(after);
  });

  it('keeps owner invitations in the current team and rejects duplicates without another audit', async () => {
    expect(await invite('owner')).toHaveProperty('success');
    expect((await sql.query('SELECT team_id,role,invited_by FROM invitations')).rows)
      .toEqual([{ team_id: 1, role: 'owner', invited_by: 1 }]);
    const after = await snapshot();
    expect(after.activity).toEqual([
      expect.objectContaining({ team_id: 1, user_id: 1, action: 'INVITE_TEAM_MEMBER' })
    ]);
    expect(await invite('owner')).toHaveProperty('error');
    expect(await snapshot()).toEqual(after);
  });

  it('does not grant membership management to a global owner without a team', async () => {
    await login(5);
    expect(await (await GET()).json()).toBeNull();
    const before = await snapshot();
    expect(await invite()).toHaveProperty('error');
    expect(await remove('3')).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
    const html = await markup();
    expect(html.match(/<input\b[^>]*\bname="email"[^>]*>/)?.[0]).toMatch(/\bdisabled/);
  });

  it('rejects unauthenticated direct removal without any writes', async () => {
    request.token = '';
    const before = await snapshot();
    await expect(remove('3')).rejects.toThrow('User is not authenticated');
    expect(await snapshot()).toEqual(before);
  });

  it('allows owners to remove members even when the roster has only two rows', async () => {
    await sql.exec('DELETE FROM team_members WHERE id = 2');
    const html = await markup();
    const buttons = [...html.matchAll(/<button\b([^>]*)>Remove<\/button>/g)];
    expect(buttons).toHaveLength(2);
    expect(buttons.every((button) => !/\bdisabled/.test(button[1]))).toBe(true);
  });

  it('disables every removal and invitation control for a member and explains both restrictions', async () => {
    await login(2);
    const html = await markup();
    const buttons = [...html.matchAll(/<button\b([^>]*)>Remove<\/button>/g)];
    expect(buttons).toHaveLength(3);
    expect(buttons.every((button) => /\bdisabled/.test(button[1]))).toBe(true);
    expect(html.match(/<input\b[^>]*\bname="email"[^>]*>/)?.[0]).toMatch(/\bdisabled/);
    expect(html).toContain('Only a team owner can remove team members.');
    expect(html).toContain('You must be a team owner to invite new members.');
    const radios = [...html.matchAll(/<button\b([^>]*\brole="radio"[^>]*)>/g)];
    expect(radios).toHaveLength(2);
    expect(radios.every((radio) => /\bdisabled/.test(radio[1]))).toBe(true);
    const inviteButton = [...html.matchAll(/<button\b([^>]*)>([\s\S]*?)<\/button>/g)]
      .find((button) => button[2].includes('Invite Member'));
    expect(inviteButton).toBeDefined();
    expect(inviteButton?.[1]).toMatch(/\bdisabled/);
  });
});

import { defineConfig } from 'vitest/config';
import acceptanceConfig from '../pureobom-validation/vitest.config.mts';

// Additional regressions run separately; the locked acceptance config is unchanged.
export default defineConfig({
  ...acceptanceConfig,
  test: {
    ...acceptanceConfig.test,
    include: ['tests/team-permissions.test.tsx']
  }
});

